function translateText(value, language) {
  if (typeof value !== 'string') return value;
  if (language === 'TH') return DICTIONARY[value] || value.replace(/^Floor (\d+)$/, 'ชั้น $1').replace(/^ชั้น (\d+)$/, 'ชั้น $1');
  return DICTIONARY_EN[value] || THAI_TO_EN[value] || value.replace(/^ชั้น (\d+)$/, 'Floor $1');
}
function localizeNode(node, language) {
  if (typeof node === 'string') return translateText(node, language);
  if (Array.isArray(node)) return node.map(child => localizeNode(child, language));
  if (!isValidElement(node)) return node;
  const children = localizeNode(node.props.children, language);
  const props = {};
  for (const key of ['placeholder', 'title', 'aria-label']) if (typeof node.props[key] === 'string') props[key] = translateText(node.props[key], language);
  if (node.type === 'option' && node.props.value === undefined && typeof node.props.children === 'string') props.value = node.props.children;
  return cloneElement(node, props, children);
}
function LocalizedUI({ language, children }) { return localizeNode(children, language); }
function Translated({ children }) { const language = useLanguage(); return <LocalizedUI language={language}>{children}</LocalizedUI>; }
