const currentIsoWeek = () => { const date = new Date(); date.setDate(date.getDate() + 4 - (date.getDay() || 7)); const year = date.getFullYear(); const first = new Date(year, 0, 1); const week = Math.ceil((((date - first) / 86400000) + 1) / 7); return `${year}-W${String(week).padStart(2, '0')}`; };
const isoWeekRange = value => { const [year, week] = value.split('-W').map(Number); const jan4 = new Date(year, 0, 4); const monday = new Date(year, 0, 4 - ((jan4.getDay() + 6) % 7) + (week - 1) * 7); const sunday = new Date(monday); sunday.setDate(monday.getDate() + 6); return [localDateKey(monday), localDateKey(sunday)]; };
