function Modal({ title, onClose, children, size = 'max-w-2xl' }) { return <Translated><div className="fixed inset-0 z-50 grid place-items-center bg-emerald-950/40 p-3 backdrop-blur-sm" onMouseDown={e => e.target === e.currentTarget && onClose()}><section role="dialog" aria-modal="true" className={`max-h-[94vh] w-full ${size} overflow-hidden rounded-2xl bg-white shadow-2xl`}><header className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div className="min-w-0"><h2 className="truncate text-base font-bold text-slate-900">{title}</h2></div><button onClick={onClose} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100" aria-label="Close"><X size={18}/></button></header><div className="max-h-[calc(94vh-64px)] overflow-y-auto p-5">{children}</div></section></div></Translated>; }
function Empty({ text }) { return <Translated><div className="grid min-h-36 place-items-center rounded-2xl border border-dashed border-slate-200 bg-white px-4 text-center text-sm text-slate-400">{text}</div></Translated>; }

