function StatCard({ label, value, hint, icon: Icon, color = 'green' }) { const colors = { green: 'bg-lime-50 text-emerald-700', sky: 'bg-sky-50 text-sky-700', rose: 'bg-rose-50 text-rose-700', amber: 'bg-amber-50 text-amber-700' }; return <Translated><div className="rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">{label}</p><b className="mt-2 block text-2xl font-bold tracking-tight tabular-nums text-slate-900">{value}</b></div><span className={`grid h-9 w-9 place-items-center rounded-xl ${colors[color]}`}><Icon size={17}/></span></div><p className="mt-2 text-[10px] text-slate-400">{hint}</p></div></Translated>; }
