function Overview({ project, floors, selectedFloor, setSelectedFloor, selectedRoom, setSelectedRoom, events, requests, roomStatus, eventsForRoom, stats, language }) {
  const [workFloor, setWorkFloor] = useState('All'); const [workRoom, setWorkRoom] = useState('All');
  const floorRows = useMemo(() => floors.map(floor => {
    if (floor === 1) {
      const passed = new Set(events.filter(event => String(event.room) === 'COMMON').flatMap(event => Object.entries(event.checklist || {}).filter(([, value]) => value === 'Pass' || value === 'Completed').map(([task]) => task))).size;
      return { floor, rooms: INSPECTION_TASKS.length, completed: passed, percent: Math.round(passed / INSPECTION_TASKS.length * 100), common: true };
    }
    const rooms = roomCountOnFloor(project, floor); const completed = new Set(events.filter(event => event.result === 'Pass' && getFloorFromRoom(event.room) === floor).map(event => String(event.room))).size;
    return { floor, rooms, completed, percent: rooms ? Math.min(100, Math.round(completed / rooms * 100)) : 0, common: false };
  }), [floors, project, events]);
  const floorsToShow = useMemo(() => floorRows.slice().reverse(), [floorRows]);
  const selectedStatus = roomStatus(selectedRoom); const roomEvents = eventsForRoom(selectedRoom);
  const taskStates = useMemo(() => roomEvents.reduce((state, event) => ({ ...state, ...(event.checklist || {}) }), {}), [roomEvents]);
  const scheduledRooms = useMemo(() => new Set(requests.flatMap(request => request.rooms)), [requests]);
  const roomsForSelectedFloor = useMemo(() => roomsOnFloor(project, selectedFloor), [project, selectedFloor]);
  const inspectionScopeEvents = useMemo(() => events.filter(event => {
    const roomFloor = String(event.room) === 'COMMON' ? 1 : getFloorFromRoom(event.room);
    if (workFloor !== 'All' && roomFloor !== Number(workFloor)) return false;
    return workRoom === 'All' || String(event.room) === String(workRoom);
  }), [events, workFloor, workRoom]);
  const workProgress = useMemo(() => INSPECTION_TASKS.map(task => {
    const latestByRoom = new Map();
    inspectionScopeEvents.slice().sort((a, b) => new Date(a.updatedAt || a.savedAt || a.date || 0) - new Date(b.updatedAt || b.savedAt || b.date || 0)).forEach(event => { const status = event.checklist?.[task.th] || event.checklist?.[task.en]; if (status) latestByRoom.set(String(event.room), status); });
    const passed = [...latestByRoom.values()].filter(status => ['Pass', 'Completed', 'ตรวจแล้ว'].includes(status)).length;
    const inProgress = [...latestByRoom.values()].filter(status => ['In Progress', 'กำลังดำเนินการ'].includes(status)).length;
    const total = workRoom !== 'All' ? 1 : workFloor === '1' ? 1 : workFloor === 'All' ? project.rooms : roomCountOnFloor(project, Number(workFloor));
    const percent = total ? Math.min(100, Math.round((passed + inProgress * .5) / total * 100)) : 0;
    return { ...task, passed, inProgress, total, percent };
  }), [inspectionScopeEvents, workRoom, workFloor, project]);
  const roomNumberForFloor = floor => roomsOnFloor(project, floor);
  const chooseFloor = floor => { setSelectedFloor(floor); setSelectedRoom(floor === 1 ? 'COMMON' : roomNumberForFloor(floor)[0]); };
  return <div className="space-y-6">
    <PageHeading eyebrow={`${project.id} · ${project.location}`} title="Project Overview" subtitle={`${project.name} · Site inspection and quality progress`} action={<Badge color="green"><Activity size={12} className="mr-1"/> LIVE PROJECT</Badge>}/>
    <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><StatCard label="Total Rooms" value={project.rooms} hint="Registered in project master data" icon={Building2}/><StatCard label="Passed Rooms" value={`${stats.passed}`} hint={`${Math.round(stats.passed / stats.total * 100)}% overall progress`} icon={CheckCircle2}/><StatCard label="Scheduled Rooms" value={stats.scheduled} hint="Included in active inspection requests" icon={Clock3} color="amber"/></section>
    <section className="grid gap-4 xl:grid-cols-[1.05fr_1fr]">
      <Card title="Building Preview" subtitle="Interactive 3D model · floor completion percentages"><BuildingModelViewer floors={floorRows} selectedFloor={selectedFloor} onSelectFloor={setSelectedFloor} language={language}/></Card>
      <Card title="Architecture Inspection Overview" subtitle="Progress for each requested work item"><div className="mb-4 grid gap-3 sm:grid-cols-2"><Field label="Floor"><select className={inputClass} value={workFloor} onChange={event => { setWorkFloor(event.target.value); setWorkRoom('All'); }}><option value="All">All Floors</option>{floors.map(floor => <option key={floor} value={floor}>{floor === 1 ? 'Floor 1 · Common Area' : `Floor ${floor}`}</option>)}</select></Field><Field label="Room"><select className={inputClass} value={workRoom} onChange={event => setWorkRoom(event.target.value)}><option value="All">All Rooms</option>{workFloor !== 'All' && roomsOnFloor(project, Number(workFloor)).map(room => <option key={room} value={room}>{room === 'COMMON' ? 'Common Area' : room}</option>)}</select></Field></div><div className="grid gap-3 sm:grid-cols-2">{workProgress.map(item => <div key={item.partId} className="rounded-xl border border-slate-100 p-3"><div className="mb-2 flex items-start justify-between gap-2"><span className="text-xs font-semibold text-slate-700">{language === 'TH' ? item.th : item.en}</span><b className="shrink-0 tabular-nums text-xs">{item.percent}%</b></div><ProgressBar value={item.percent} color={item.inProgress ? 'bg-amber-400' : 'bg-lime-500'}/><p className="mt-2 text-[10px] text-slate-400">{item.passed}/{item.total} passed{item.inProgress ? ` · ${item.inProgress} in progress` : ''}</p></div>)}</div></Card>
    </section>
    <section className="grid gap-4 xl:grid-cols-[.85fr_1fr_1.4fr]">
      <Card title="Floor Status" subtitle="Select a floor to inspect"><div className="space-y-1.5">{floorsToShow.map(row => <button key={row.floor} onClick={() => chooseFloor(row.floor)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left ${selectedFloor === row.floor ? 'bg-emerald-950 text-white' : 'hover:bg-slate-50'}`}><span className="w-24 shrink-0 text-xs font-semibold">{row.common ? (language === 'TH' ? 'ชั้น 1 · ส่วนกลาง' : '1F · Common') : language === 'TH' ? `ชั้น ${row.floor}` : `Floor ${row.floor}`}</span><span className="flex-1"><ProgressBar value={row.percent} color={selectedFloor === row.floor ? 'bg-lime-400' : 'bg-lime-500'}/></span><span className={`shrink-0 text-[10px] tabular-nums ${selectedFloor === row.floor ? 'text-emerald-100' : 'text-slate-400'}`}>{row.percent}%</span></button>)}</div><div className="mt-4 flex flex-wrap gap-2 border-t border-slate-100 pt-4 text-[10px]"><Badge color="green">Pass</Badge><Badge color="amber">In Progress</Badge><Badge>Not started</Badge></div></Card>
      <Card title={selectedFloor === 1 ? (language === 'TH' ? 'พื้นที่ส่วนกลาง · ชั้น 1' : 'Common Area · Floor 1') : `${language === 'TH' ? 'ผังชั้น' : 'Floor Plan'} · ${language === 'TH' ? `ชั้น ${selectedFloor}` : `Floor ${selectedFloor}`}`} subtitle={selectedFloor === 1 ? 'Common Area Progress' : 'Select a room to view its inspection status'} action={<Badge>{selectedFloor === 1 ? 'COMMON' : `${roomsForSelectedFloor.length} ROOMS`}</Badge>}><div className="grid grid-cols-3 gap-2 sm:grid-cols-4">{roomsForSelectedFloor.map(room => { const status = roomStatus(room); const style = status === 'Pass' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : status === 'Fail' ? 'border-rose-200 bg-rose-50 text-rose-800' : scheduledRooms.has(room) ? 'border-amber-200 bg-amber-50 text-amber-800' : 'border-slate-200 bg-slate-50 text-slate-500'; return <button key={room} onClick={() => setSelectedRoom(room)} className={`relative grid min-h-[58px] place-items-center rounded-xl border text-xs font-bold transition hover:-translate-y-0.5 ${style} ${selectedRoom === room ? 'ring-2 ring-lime-400 ring-offset-2' : ''}`}><span>{room === 'COMMON' ? (language === 'TH' ? 'ส่วนกลาง' : 'Common') : room}</span><i className={`absolute bottom-2 h-1.5 w-1.5 rounded-full ${STATUS[status]?.dot || 'bg-slate-300'}`}/></button>; })}</div></Card>
      <Card title={language === 'TH' ? 'แบบขยายห้องพัก' : 'Room 3D View'} subtitle={`${selectedRoom === 'COMMON' ? (language === 'TH' ? 'พื้นที่ส่วนกลาง' : 'Common Area') : (language === 'TH' ? 'ห้อง' : 'Room')} ${selectedRoom}`} action={<ResultBadge status={selectedStatus}/> }><RoomModelViewer3D room={selectedRoom} taskStates={taskStates} language={language}/><div className="mt-3 space-y-2">{roomEvents.length ? roomEvents.slice(-2).map(e => <div key={e.id} className="rounded-xl bg-slate-50 p-3"><div className="flex justify-between gap-2"><span className="text-[11px] font-semibold">{e.stage}</span><ResultBadge status={e.result}/></div><p className="mt-1 text-[10px] text-slate-500">{e.note || '—'}</p></div>) : <p className="text-xs text-slate-400">No inspection event recorded for this location.</p>}</div></Card>
    </section>
  </div>;
}

function RequestSchedule({ project, requests, filter, setFilter, search, setSearch, month, setMonth, todayValue, canEdit, onCreate, onOpen, onReschedule }) {
  const language = useContext(LanguageContext);
  const filtered = useMemo(() => requests.filter(r => (filter === 'All Status' || r.status === filter) && `${r.requestNo} ${r.rooms.join(' ')} ${getRequestedWorks(r).join(' ')}`.toLowerCase().includes(search.toLowerCase())), [requests, filter, search]);
  const monthLabel = month.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const { offset, days } = calendarBounds(month.getFullYear(), month.getMonth());
  const [todayYear, todayMonth, todayDay] = todayValue.split('-').map(Number);
  const calendarCells = [...Array(offset).fill(null), ...Array.from({ length: days }, (_, i) => i + 1)];
  const prev = () => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1)); const next = () => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1));
  const requestsOnDay = n => requests.filter(r => r.appointment === `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, '0')}-${String(n).padStart(2, '0')}`);
  return <div className="space-y-6"><PageHeading eyebrow={`${project.id} · Inspection planning`} title="Request & Schedule" subtitle="Create inspection requests, coordinate rooms and review upcoming appointments" action={<Button onClick={onCreate} disabled={!canEdit}><Plus size={16}/>Create Inspection Request</Button>}/>{!canEdit && <ReadOnlyNotice/>}
    <div className="grid items-start gap-4 2xl:grid-cols-[1.3fr_.9fr]"><Card title="Inspection Request List" subtitle={`${filtered.length} requests`} action={<div className="flex flex-wrap gap-2"><div className="relative"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="ค้นหาเลขห้อง / เลขที่เอกสารคำขอ" className={`${inputClass} pl-9 sm:w-64`}/></div><select value={filter} onChange={e => setFilter(e.target.value)} className={`${inputClass} sm:w-48`}><option>All Status</option><option>Scheduled</option><option>Partially Inspected</option><option>Completed</option></select></div>}><div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-xs"><thead><tr className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400">{['REQUEST NO.','WORK STAGE','ROOMS','APPOINTMENT','STATUS','ACTIONS'].map(x => <th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{filtered.map(r => <tr key={r.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70"><td className="px-3 py-3"><b className="block text-emerald-900">{r.requestNo}</b><small className="text-slate-400">Rev. {r.rev ?? r.rootId ?? '00'}</small></td><td className="px-3 py-3">{getRequestedWorks(r).join(' · ')}</td><td className="px-3 py-3">{r.rooms.length} rooms</td><td className="px-3 py-3">{r.appointment}<small className="ml-2 text-slate-400">{r.time}</small></td><td className="px-3 py-3"><ResultBadge status={r.status}/></td><td className="px-3 py-3"><div className="flex gap-1"><Button variant="ghost" className="min-h-8 px-2 text-xs" onClick={() => onOpen(r)}><Eye size={14}/>Open</Button><Button variant="ghost" className="min-h-8 px-2 text-xs" disabled={!canEdit} onClick={() => onReschedule(r)}><CalendarDays size={14}/>Reschedule</Button></div></td></tr>)}</tbody></table>{!filtered.length && <Empty text="No requests match these filters."/>}</div></Card>
    <Card title="Monthly Schedule Calendar" subtitle={monthLabel}><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2"><button onClick={prev} className="rounded-lg p-2 hover:bg-slate-100" aria-label="Previous month"><ChevronLeft size={17}/></button><b className="text-sm">{monthLabel}</b><button onClick={next} className="rounded-lg p-2 hover:bg-slate-100" aria-label="Next month"><ChevronRight size={17}/></button></div><Badge color="green">Today · {todayDay}</Badge></div><div className="grid grid-cols-7 border-l border-t border-slate-100 text-center text-[10px] text-slate-400">{['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d => <span key={d} className="border-b border-r border-slate-100 bg-slate-50 py-2 font-bold">{d}</span>)}{calendarCells.map((day, i) => { const isToday = day === todayDay && month.getFullYear() === todayYear && month.getMonth() + 1 === todayMonth; return <div key={`${day}-${i}`} className={`min-h-[72px] border-b border-r border-slate-100 p-1 text-left ${isToday ? 'bg-lime-50/60' : ''}`}><span className={`grid h-5 w-5 place-items-center rounded-full text-[10px] ${isToday ? 'bg-lime-400 font-bold text-emerald-950' : 'text-slate-500'}`}>{day || ''}</span>{day && requestsOnDay(day).slice(0, 2).map(r => <button key={r.id} onClick={() => onOpen(r)} className="mt-1 block w-full truncate rounded bg-emerald-50 px-1 py-1 text-left text-[9px] font-semibold text-emerald-800 hover:bg-lime-100">{r.time} · {r.rooms[0]}</button>)}</div>; })}</div></Card></div>
  </div>;
}

function ReadOnlyNotice() { return <Translated><div className="flex items-start gap-3 rounded-xl border border-sky-200 bg-sky-50 p-3 text-xs text-sky-900"><ShieldCheck size={17} className="mt-0.5 shrink-0"/><p><b>Read-only access.</b> Guest can view and download project records. Create, upload, edit and delete actions are disabled.</p></div></Translated>; }

function InspectionsPage({ project, requests, events, view, setView, canEdit, drafts, onInspect, onResumeDraft, onView, onDeleteDraft }) {
  const activeRequests = useMemo(() => requests.filter(r => r.status !== 'Completed'), [requests]);
  const historyRequests = useMemo(() => requests.filter(r => r.status === 'Completed' || events.some(e => e.requestId === r.id)), [requests, events]);
  const rows = view === 'My Inspection' ? activeRequests : historyRequests;
  return <div className="space-y-6"><PageHeading eyebrow={`${project.id} · Site quality`} title="Inspections" subtitle="Inspect assigned rooms, save drafts and review past inspection results" action={<select className={`${inputClass} w-auto`} value={view} onChange={e => setView(e.target.value)}><option>My Inspection</option><option>History</option></select>}/>{!canEdit && <ReadOnlyNotice/>}{view === 'My Inspection' && drafts.length > 0 && <Card title="Saved Drafts" subtitle="Continue an inspection later"><div className="grid gap-2 sm:grid-cols-2">{drafts.map(d => <div key={d.id} className="flex items-center justify-between gap-3 rounded-xl bg-amber-50 p-3"><div><b className="text-xs">{d.requestNo} · Room {d.room}</b><p className="mt-1 text-[10px] text-slate-500">{d.stage} · {formatDateTime(d.savedAt)}</p></div><div className="flex gap-1"><Button variant="secondary" className="min-h-8 px-2 text-[10px]" disabled={!canEdit} onClick={() => onResumeDraft(d)}>Resume</Button>{canEdit && <button className="rounded-lg p-2 text-rose-500 hover:bg-rose-100" onClick={() => onDeleteDraft(d.id)} title="Delete draft"><Trash2 size={15}/></button>}</div></div>)}</div></Card>}
    <Card title={view === 'My Inspection' ? 'My Inspection Queue' : 'Inspection History'} subtitle={view === 'My Inspection' ? 'Requests waiting for the site engineer' : 'Completed and previously inspected requests'}><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-xs"><thead><tr className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400">{['REQUEST','SCHEDULE','ROOM(S)','WORK STAGE','PROGRESS','STATUS','ACTIONS'].map(x => <th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{rows.map(r => { const records = events.filter(e => e.requestId === r.id); const completed = new Set(records.map(e => String(e.room))).size; const result = records.some(e => e.result === 'Fail') ? 'Fail' : r.status === 'Completed' ? 'Pass' : 'Pending'; return <tr key={r.id} className="border-b border-slate-50 last:border-0"><td className="px-3 py-4"><b className="text-emerald-900">{r.requestNo}</b><p className="mt-1 text-[10px] text-slate-500">{r.title}</p></td><td className="px-3 py-4">{r.appointment}<span className="ml-2 text-slate-400">{r.time}</span></td><td className="px-3 py-4">{r.rooms.map(room => <span key={room} className="mr-1 inline-block rounded bg-slate-100 px-1.5 py-1 text-[10px]">{room}</span>)}</td><td className="px-3 py-4">{r.stage}</td><td className="px-3 py-4"><b>{completed}/{r.rooms.length}</b><div className="mt-1 w-20"><ProgressBar value={completed / r.rooms.length * 100}/></div></td><td className="px-3 py-4"><ResultBadge status={view === 'History' ? result : r.status}/></td><td className="px-3 py-4"><div className="flex flex-wrap gap-1">{view === 'History' && records.length > 0 && <Button variant="ghost" className="min-h-8 px-2 text-[10px]" onClick={() => onView(records[records.length - 1])}><Eye size={13}/>ดูผลตรวจ</Button>}<Button variant="primary" className="min-h-8 px-2 text-[10px]" disabled={!canEdit || (view === 'My Inspection' && r.status === 'Completed')} onClick={() => onInspect(r, records.at(-1))}>{view === 'History' ? 'Retry' : 'เปิดตรวจ'}</Button></div></td></tr>; })}</tbody></table>{rows.length === 0 && <Empty text={view === 'My Inspection' ? 'No active inspection requests.' : 'No inspection history yet.'}/>}</div></Card>
  </div>;
}

function DocumentsPage({ project, events, requests, docs, packs, canEdit, search, setSearch, filters, setFilters, onUpload, onEdit, onDelete, onView, onPacks, summarySearch, setSummarySearch, onToast }) {
  const [view, setView] = useState('Inspection Summary');
  const [packForm, setPackForm] = useState({ contractor: '', period: '', workPackage: '', requestFilter: 'All', include: { events: true, photos: true, defects: true, ri: true, history: true } });
  const [selectedPack, setSelectedPack] = useState(null);
  const [dateMode, setDateMode] = useState('selected'); const [selectedDate, setSelectedDate] = useState(todayIso);
  const [reportMode, setReportMode] = useState('monthly'); const [reportWeek, setReportWeek] = useState(currentIsoWeek); const [reportMonth, setReportMonth] = useState(() => todayIso().slice(0, 7));
  const [previewPhoto, setPreviewPhoto] = useState(null);
  const allRows = useMemo(() => events.filter(e => `${e.requestNo} ${e.room} ${e.recorder} ${e.defect}`.toLowerCase().includes(summarySearch.toLowerCase())), [events, summarySearch]);
  const filteredDocs = useMemo(() => docs.filter(doc => (filters.building === 'All' || doc.building === filters.building) && (filters.floor === 'All' || String(doc.floor) === filters.floor) && (filters.room === 'All' || String(doc.room) === filters.room) && (filters.round === 'All' || doc.round === filters.round) && (dateMode === 'all' || localDateKey(doc.appointment_date || doc.scheduledDate || doc.date || doc.uploadedAt || doc.updated_at) === selectedDate) && `${doc.name} ${doc.requestNo} ${doc.room} ${doc.type}`.toLowerCase().includes(search.toLowerCase())), [docs, filters, dateMode, selectedDate, search]);
  const reportRange = useMemo(() => reportMode === 'weekly' ? isoWeekRange(reportWeek) : [`${reportMonth}-01`, `${reportMonth}-${String(new Date(Number(reportMonth.slice(0, 4)), Number(reportMonth.slice(5, 7)), 0).getDate()).padStart(2, '0')}`], [reportMode, reportWeek, reportMonth]);
  const reportPhotos = useMemo(() => events.filter(event => { const date = localDateKey(event.date || event.updated_at); return date >= reportRange[0] && date <= reportRange[1]; }).flatMap(event => (event.evidence || []).filter(photo => photo.dataUrl?.startsWith('data:image/')).map(photo => ({ ...photo, event }))), [events, reportRange]);
  const summaryCards = useMemo(() => [
    { label: 'จำนวนบันทึก', value: events.length, icon: FileCheck2, color: 'green' },
    { label: 'Pass Result', value: events.filter(e => e.result === 'Pass').length, icon: CheckCircle2, color: 'green' },
    { label: 'รายการ / Defect', value: events.filter(e => e.result === 'Fail').length, icon: AlertTriangle, color: 'rose' },
    { label: 'Evidence Files', value: events.reduce((n, e) => n + e.evidence.length, 0), icon: FileText, color: 'sky' },
  ], [events]);
  const exportCsv = () => { const headers = ['DATE','REQUEST','ROOM','RECORDER','RESULT','DEFECT','EVIDENCE']; const lines = [headers, ...allRows.map(e => [e.date, e.requestNo, e.room, e.recorder, e.result, e.defect, e.evidence.map(x => x.name).join('; ')])].map(row => row.map(csvEscape).join(',')).join('\r\n'); saveDownload(`trex-inspection-summary-${project.id}.csv`, `\uFEFF${lines}`, 'text/csv;charset=utf-8'); };
  const generatePack = e => { e.preventDefault(); if (!packForm.contractor.trim() || !packForm.period.trim() || !packForm.workPackage.trim()) { onToast('Complete contractor, claim period and work package first.'); return; } const pack = { id: uid(), projectId: project.id, ...packForm, createdAt: new Date().toISOString(), eventIds: events.map(x => x.id), docIds: docs.map(x => x.id) }; onPacks([pack]); onToast('Claim evidence pack generated.'); };
  const downloadPack = pack => { const content = JSON.stringify({ ...pack, events, documents: docs, requests }, null, 2); saveDownload(`${pack.id}-claim-evidence-pack.json`, content, 'application/json'); };
  return <div className="space-y-6"><PageHeading eyebrow={`${project.id} · Project records`} title="Document" subtitle="Inspection history, claim evidence packs and project document repository" action={<select value={view} onChange={e => setView(e.target.value)} className={`${inputClass} w-auto`}><option>Inspection Summary</option><option>Claim Evidence Pack</option><option>Document Hub</option></select>}/>{!canEdit && <ReadOnlyNotice/>}
    {view === 'Inspection Summary' && <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{summaryCards.map(s => <StatCard key={s.label} label={s.label} value={s.value} hint="Current project records" icon={s.icon} color={s.color}/>)}</div><Card title="Inspection Activity Summary" subtitle="Exportable inspection records" action={<div className="flex flex-wrap gap-2"><div className="relative"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${inputClass} pl-9 sm:w-52`} placeholder="Search Request / Room" value={summarySearch} onChange={e => setSummarySearch(e.target.value)}/></div><Button variant="secondary" onClick={exportCsv}><Download size={15}/>Export CSV</Button><Button variant="secondary" onClick={() => window.print()}><Printer size={15}/>Print / Save PDF</Button></div>}><SummaryTable events={allRows} onEvent={e => onToast(`${e.requestNo} · Room ${e.room} · ${e.result}`)}/></Card></>}
    {view === 'Claim Evidence Pack' && <div className="grid items-start gap-4 xl:grid-cols-[1fr_.8fr]"><Card title="Generate Claim Evidence Pack" subtitle="Choose the evidence set to include"><form onSubmit={generatePack} className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Contractor / ผู้รับเหมา"><input className={inputClass} value={packForm.contractor} onChange={e => setPackForm({ ...packForm, contractor: e.target.value })} placeholder="Contractor name"/></Field><Field label="Claim Period"><input className={inputClass} value={packForm.period} onChange={e => setPackForm({ ...packForm, period: e.target.value })} type="month"/></Field><Field label="Work Package"><select className={inputClass} value={packForm.workPackage} onChange={e => setPackForm({ ...packForm, workPackage: e.target.value })}><option value="">Choose work package</option>{WORK_TYPES.map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Request Filter"><select className={inputClass} value={packForm.requestFilter} onChange={e => setPackForm({ ...packForm, requestFilter: e.target.value })}><option>All</option>{requests.map(r => <option key={r.id} value={r.requestNo}>{r.requestNo}</option>)}</select></Field></div><div className="grid gap-2 sm:grid-cols-2">{[['events','Inspection Events'],['photos','Site Photos'],['defects','Defect Status'],['ri','Inspection Request / RI'],['history','Room History']].map(([key,label]) => <label key={key} className="flex items-center gap-2 rounded-xl border border-slate-100 p-3 text-xs"><input type="checkbox" checked={packForm.include[key]} onChange={e => setPackForm({ ...packForm, include: { ...packForm.include, [key]: e.target.checked } })} className="accent-lime-500"/>{label}</label>)}</div><Button type="submit" disabled={!canEdit}><FilePlus2 size={15}/>Generate Claim Evidence Pack</Button></form></Card><Card title="Generated Packs" subtitle={`${packs.length} packs in this project`}><div className="space-y-2">{packs.map(pack => <div key={pack.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><b className="text-xs">{pack.contractor}</b><p className="mt-1 text-[10px] text-slate-500">{pack.workPackage} · {pack.period} · {pack.id.slice(0,8)}</p></div><div className="flex gap-1"><Button variant="secondary" className="min-h-8 px-2 text-[10px]" onClick={() => setSelectedPack(pack)}><Eye size={13}/>Preview</Button><Button variant="secondary" className="min-h-8 px-2 text-[10px]" onClick={() => downloadPack(pack)}><Download size={13}/>Download</Button></div></div>)}{!packs.length && <Empty text="Generated evidence packs will appear here."/>}</div></Card></div>}
    {view === 'Document Hub' && <><Card title="Document Hub" subtitle="Search project files by building, floor, room and inspection round" action={<div className="flex flex-wrap gap-2"><div className="relative"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input className={`${inputClass} pl-9 sm:w-64`} placeholder="Search documents or requests" value={search} onChange={e => setSearch(e.target.value)}/></div>{canEdit && <Button onClick={onUpload}><Upload size={15}/>Upload Document</Button>}</div>}>
      <div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-5"><div className="flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-800"><Building2 size={14}/>{project.id}</div><select className={inputClass} value={filters.building} onChange={e => setFilters({ ...filters, building: e.target.value, floor: 'All', room: 'All' })}><option>All</option><option>Building A</option><option>Building B</option></select><select className={inputClass} value={filters.floor} onChange={e => setFilters({ ...filters, floor: e.target.value })}><option>All</option>{Array.from({ length: project.floors }, (_, i) => String(i + 1)).map(x => <option key={x} value={x}>ชั้น {x}</option>)}</select><select className={inputClass} value={filters.room} onChange={e => setFilters({ ...filters, room: e.target.value })}><option>All</option>{[...new Set(docs.map(x => String(x.room)))].sort().map(x => <option key={x}>{x}</option>)}</select><select className={inputClass} value={filters.round} onChange={e => setFilters({ ...filters, round: e.target.value })}><option>All</option>{[...new Set(docs.map(x => x.round))].map(x => <option key={x}>{x}</option>)}</select></div>
      <div className="mb-4 flex flex-wrap items-end gap-2 rounded-xl bg-slate-50 p-3"><label className="min-w-40 flex-1 text-[10px] font-semibold text-slate-500">ตัวกรองวันที่ / Filter by Date<select className={`${inputClass} mt-1`} value={dateMode} onChange={e => setDateMode(e.target.value)}><option value="selected">เฉพาะวันที่เลือก · Selected Date Only</option><option value="all">ทุกวัน · All Dates</option></select></label>{dateMode === 'selected' && <label className="min-w-40 flex-1 text-[10px] font-semibold text-slate-500">วันที่ / Date<input type="date" className={`${inputClass} mt-1`} value={selectedDate} onChange={e => setSelectedDate(e.target.value)}/></label>}<Badge color="sky">แสดง {filteredDocs.length} เอกสาร / Showing {filteredDocs.length} documents</Badge>{dateMode === 'selected' && <Button type="button" variant="secondary" className="min-h-9" onClick={() => setDateMode('all')}>ดูทุกวัน / All Dates</Button>}{dateMode === 'all' && <Button type="button" variant="secondary" className="min-h-9" onClick={() => setDateMode('selected')}>กลับไปวันที่เลือก / Selected Date</Button>}</div>
      <div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left text-xs"><thead><tr className="border-b border-slate-100 text-[10px] uppercase tracking-wide text-slate-400">{['DOCUMENT','TYPE','REQUEST','ROOM','DATE','รายละเอียด'].map(x => <th key={x} className="px-3 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{filteredDocs.map(doc => { const linkedEvents = events.filter(event => event.requestNo === doc.requestNo && String(event.room) === String(doc.room)); const photos = linkedEvents.flatMap(event => (event.evidence || []).filter(file => file.dataUrl?.startsWith('data:image/')).map(file => ({ ...file, event }))); return <tr key={doc.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70"><td className="px-3 py-3"><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-emerald-50 text-emerald-700"><FileText size={15}/></span><span><b className="block">{doc.name}</b><small className="text-slate-400">{doc.size || 'File'} · {doc.building} · Floor {doc.floor}</small><span className="mt-1 block text-[10px] text-slate-500">{linkedEvents.length ? `ตรวจแล้ว / Inspected · ${linkedEvents.at(-1).result} · ${linkedEvents.at(-1).date}` : 'ยังไม่ตรวจ / Not Inspected'}{linkedEvents.length && !photos.length ? ' · ไม่มีรูปประกอบ / No Photo Evidence' : ''}</span>{photos.length > 0 && <span className="mt-1 flex items-center gap-1.5">{photos.map((photo, index) => <button key={`${photo.id || photo.name}-${index}`} type="button" onClick={() => setPreviewPhoto(photo)} title="ตัวอย่างรูปประกอบการตรวจงาน / Inspection Photo Evidence"><img src={photo.dataUrl} alt={photo.name || 'Inspection evidence'} className="h-10 w-12 rounded-md border border-slate-200 object-cover"/></button>)}</span>}</span></div></td><td className="px-3 py-3"><Badge>{doc.type}</Badge></td><td className="px-3 py-3">{doc.requestNo}</td><td className="px-3 py-3">{doc.room}</td><td className="px-3 py-3">{localDateKey(doc.appointment_date || doc.scheduledDate || doc.date || doc.uploadedAt || doc.updated_at)}</td><td className="px-3 py-3"><div className="flex gap-1"><Button variant="ghost" className="min-h-8 px-2 text-[10px]" onClick={() => onView(doc)}><Eye size={13}/>View</Button>{canEdit && <><Button variant="ghost" className="min-h-8 px-2 text-[10px]" onClick={() => onEdit(doc)}><Pencil size={13}/></Button><Button variant="ghost" className="min-h-8 px-2 text-[10px] text-rose-600" onClick={() => onDelete(doc)}><Trash2 size={13}/></Button></>}</div></td></tr>; })}</tbody></table>{!filteredDocs.length && <Empty text={dateMode === 'selected' ? `No documents for ${selectedDate}. Reset to All Dates to view other files.` : 'No documents match the selected filters.'}/>}</div>
      </Card><Card title="รูปตรวจงานสำหรับรายงาน / Collected Inspection Photos for Report" subtitle="รวบรวมรูปตรวจตามสัปดาห์หรือเดือน · Collect inspection photos by week or month"><div className="flex flex-wrap items-end gap-2"><label className="min-w-36 flex-1 text-[10px] font-semibold text-slate-500">ช่วงรายงาน / Report Period<select className={`${inputClass} mt-1`} value={reportMode} onChange={e => setReportMode(e.target.value)}><option value="weekly">รายสัปดาห์ · Weekly</option><option value="monthly">รายเดือน · Monthly</option></select></label>{reportMode === 'weekly' ? <label className="min-w-36 flex-1 text-[10px] font-semibold text-slate-500">สัปดาห์ / Week<input type="week" className={`${inputClass} mt-1`} value={reportWeek} onChange={e => setReportWeek(e.target.value)}/></label> : <label className="min-w-36 flex-1 text-[10px] font-semibold text-slate-500">เดือน / Month<input type="month" className={`${inputClass} mt-1`} value={reportMonth} onChange={e => setReportMonth(e.target.value)}/></label>}<Badge color="green">{reportPhotos.length} photos · {reportRange[0]} — {reportRange[1]}</Badge><Button type="button" variant="secondary" onClick={() => saveDownload(`trex-${reportMode}-photos-${reportMode === 'weekly' ? reportWeek : reportMonth}.json`, JSON.stringify(reportPhotos.map(({ id, name, event }) => ({ id, name, requestNo: event.requestNo, room: event.room, date: event.date, result: event.result })), null, 2), 'application/json')}><Download size={14}/>Export List</Button></div>{reportPhotos.length ? <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{reportPhotos.map((photo, index) => <div key={`${photo.event.id}-${photo.id || photo.name}-${index}`} className="overflow-hidden rounded-xl border border-slate-200"><button type="button" onClick={() => setPreviewPhoto(photo)} className="block w-full"><img src={photo.dataUrl} alt={photo.name || 'Inspection evidence'} className="h-28 w-full object-cover"/></button><div className="p-2"><p className="truncate text-[10px] font-semibold">{photo.event.requestNo} · {photo.event.room}</p><p className="text-[9px] text-slate-500">{photo.event.date} · {photo.event.result}</p><a href={photo.dataUrl} download={photo.name || 'inspection-photo.jpg'} className="mt-1 inline-block text-[10px] font-semibold text-emerald-700">Download photo</a></div></div>)}</div> : <p className="mt-4 rounded-xl bg-slate-50 p-3 text-xs text-slate-500">{reportRange[0]} — {reportRange[1]} · No inspection photo evidence in this period.</p>}</Card></>}
    {previewPhoto && <Modal title="ตัวอย่างรูปประกอบการตรวจงาน / Inspection Photo Evidence" onClose={() => setPreviewPhoto(null)} size="max-w-4xl"><div className="space-y-3"><img src={previewPhoto.dataUrl} alt={previewPhoto.name || 'Inspection evidence'} className="mx-auto max-h-[70vh] max-w-full rounded-xl object-contain"/><p className="text-xs text-slate-500">{previewPhoto.event?.requestNo || ''} · Room {previewPhoto.event?.room || ''} · {previewPhoto.event?.date || ''}</p><div className="flex justify-end gap-2"><a className="inline-flex items-center rounded-xl border px-3 py-2 text-sm font-semibold" href={previewPhoto.dataUrl} target="_blank" rel="noopener noreferrer">Open image</a><a className="inline-flex items-center rounded-xl bg-lime-500 px-3 py-2 text-sm font-semibold" href={previewPhoto.dataUrl} download={previewPhoto.name || 'inspection-photo.jpg'}>Download</a></div></div></Modal>}
    {selectedPack && <Modal title="Claim Evidence Pack Preview" onClose={() => setSelectedPack(null)}><div className="space-y-3"><div className="rounded-xl bg-emerald-50 p-4"><b className="text-sm">{selectedPack.contractor}</b><p className="mt-1 text-xs text-slate-600">{selectedPack.workPackage} · {selectedPack.period}</p></div><p className="text-xs">Includes {Object.entries(selectedPack.include).filter(([,v]) => v).map(([k]) => k).join(', ')}</p><p className="text-xs text-slate-500">{selectedPack.eventIds.length} inspection records · {selectedPack.docIds.length} documents</p><Button onClick={() => downloadPack(selectedPack)}><Download size={14}/>Download Pack</Button></div></Modal>}
  </div>;
}

function SummaryTable({ events, onEvent }) { return <Translated><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead><tr className="border-b border-slate-100 text-[10px] uppercase text-slate-400">{['DATE','REQUEST','ROOM','RECORDER','RESULT','DEFECT','EVIDENCE'].map(x => <th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{events.map(event => <tr key={event.id} onClick={() => onEvent(event)} className="cursor-pointer border-b border-slate-50 last:border-0 hover:bg-slate-50"><td className="px-3 py-3">{event.date}</td><td className="px-3 py-3 font-semibold text-emerald-900">{event.requestNo}</td><td className="px-3 py-3">{event.room}</td><td className="px-3 py-3">{event.recorder}</td><td className="px-3 py-3"><ResultBadge status={event.result}/></td><td className="max-w-[180px] truncate px-3 py-3">{event.defect || '—'}</td><td className="px-3 py-3">{event.evidence.length}</td></tr>)}</tbody></table>{!events.length && <Empty text="No inspection records found."/>}</div></Translated>; }

function fileToDataUrl(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); }
async function compressImage(file) {
  if (!file.type.startsWith('image/')) return await fileToDataUrl(file);
  const source = await fileToDataUrl(file);
  return new Promise(resolve => { const img = new Image(); img.onload = () => { const scale = Math.min(1, 1400 / Math.max(img.width, img.height)); const canvas = document.createElement('canvas'); canvas.width = Math.round(img.width * scale); canvas.height = Math.round(img.height * scale); canvas.getContext('2d')?.drawImage(img, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL('image/jpeg', .78)); }; img.onerror = () => resolve(source); img.src = source; });
}
function downloadRecord(record, fallbackName = 'trex-record') {
  if (record.dataUrl) { const a = document.createElement('a'); a.href = record.dataUrl; a.download = record.name || fallbackName; a.click(); return; }
  if (record.evidence?.dataUrl) { const a = document.createElement('a'); a.href = record.evidence.dataUrl; a.download = record.evidence.name || fallbackName; a.click(); return; }
  saveDownload(`${fallbackName}.txt`, JSON.stringify(record, null, 2));
}

function AppModal({ modal, project, floors, requests, events, user, updateData, onClose, onToast, onCamera, onStopCamera, onCapture, videoRef, cameraState, language }) {
  if (modal.type === 'request') return <RequestModal project={project} request={modal.request} onClose={onClose} onToast={onToast} updateData={updateData}/>;
  if (modal.type === 'request-detail') return <Modal title={`Inspection Request · ${modal.request.requestNo}`} onClose={onClose}><RequestDetail request={modal.request} onClose={onClose}/></Modal>;
  if (modal.type === 'inspection') return <InspectionModal project={project} request={modal.request} event={modal.event} draft={modal.draft} user={user} events={events} updateData={updateData} onClose={onClose} onToast={onToast} onCamera={onCamera} onStopCamera={onStopCamera} onCapture={onCapture} videoRef={videoRef} cameraState={cameraState} language={language}/>;
  if (modal.type === 'event-detail') return <Modal title="Inspection Result" onClose={onClose}><EventDetail event={modal.event} onClose={onClose}/></Modal>;
  if (modal.type === 'document') return <DocumentModal project={project} doc={modal.doc} requests={requests} floors={floors} onClose={onClose} onToast={onToast} updateData={updateData}/>;
  if (modal.type === 'delete-doc') return <Modal title="Delete Document" onClose={onClose} size="max-w-md"><p className="text-sm text-slate-600">Delete <b>{modal.doc.name}</b> from this prototype project?</p><div className="mt-5 flex justify-end gap-2"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button variant="danger" onClick={() => { updateData(c => ({ ...c, docs: c.docs.filter(d => d.id !== modal.doc.id) })); onToast('Document deleted.'); onClose(); }}><Trash2 size={15}/>Delete</Button></div></Modal>;
  if (modal.type === 'document-detail') return <DocumentDetail doc={modal.doc} onClose={onClose}/>;
  return null;
}

function RequestModal({ project, request, onClose, onToast, updateData }) {
  const language = useContext(LanguageContext);
  const priorWorks = request ? getRequestedWorks(request) : [];
  const [form, setForm] = useState(() => request ? { ...request, rooms: [...request.rooms], rev: request.rev ?? request.rootId ?? '' } : { requestNo: `RI-${project.id.slice(2)}-${String(Date.now()).slice(-3)}`, rev: '', appointment: todayIso(), time: '09:00', coordinator: 'Phattarawadee Sroiphap', rooms: [], attachmentNames: [] });
  const [selectedWorks, setSelectedWorks] = useState(() => priorWorks.filter(item => REQUEST_WORKS.includes(item)).concat(priorWorks.some(item => !REQUEST_WORKS.includes(item)) ? [OTHER_WORK] : []));
  const [otherWork, setOtherWork] = useState(() => priorWorks.find(item => !REQUEST_WORKS.includes(item)) || request?.otherWork || '');
  const firstRoom = request?.rooms?.[0] || '';
  const [selectedFloor, setSelectedFloor] = useState(() => firstRoom === 'COMMON' ? 1 : Math.max(2, getFloorFromRoom(firstRoom) || 2));
  const roomIds = useMemo(() => roomsOnFloor(project, selectedFloor), [project, selectedFloor]);
  const [error, setError] = useState('');
  const set = (key, value) => setForm(f => ({ ...f, [key]: value }));
  const toggleRoom = room => set('rooms', form.rooms.includes(room) ? form.rooms.filter(x => x !== room) : [...form.rooms, room]);
  const toggleWork = item => setSelectedWorks(current => current.includes(item) ? current.filter(value => value !== item) : [...current, item]);
  const submit = e => { e.preventDefault(); const requestedWorks = [...selectedWorks.filter(item => item !== OTHER_WORK), ...(selectedWorks.includes(OTHER_WORK) && otherWork.trim() ? [otherWork.trim()] : [])]; if (selectedWorks.includes(OTHER_WORK) && !otherWork.trim()) { setError('ระบุรายการตรวจอื่นๆ ก่อนบันทึก · Enter the custom work item before saving.'); return; } if (!form.requestNo.trim() || !form.appointment || !form.rooms.length || !requestedWorks.length) { setError('กรอกข้อมูลที่จำเป็น เลือกรายการตรวจ และเลือกอย่างน้อยหนึ่งห้อง · Complete required fields, select work items, and select at least one room.'); return; } const next = { ...form, rev: form.rev.trim(), rootId: form.rev.trim(), requestedWorks, otherWork: otherWork.trim(), stage: requestedWorks.join(' · '), id: request?.id || uid(), projectId: project.id, status: request?.status || 'Scheduled', createdAt: request?.createdAt || new Date().toISOString() }; updateData(c => ({ ...c, requests: request ? c.requests.map(r => r.id === request.id ? next : r) : [next, ...c.requests] })); onToast(request ? 'Inspection request updated.' : 'Inspection request created and added to Inspections.'); onClose(); };
  const handleFiles = e => { const files = [...e.target.files || []]; set('attachmentNames', [...new Set([...form.attachmentNames, ...files.map(f => f.name)])]); };
  return <Modal title={request ? 'Reschedule / Edit Inspection Request' : 'Create Inspection Request'} onClose={onClose} size="max-w-4xl"><form onSubmit={submit} className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Project"><input className={`${inputClass} bg-slate-50`} readOnly value={`${project.id} · ${project.name}`}/></Field><Field label="Request No."><input className={inputClass} value={form.requestNo} onChange={e => set('requestNo', e.target.value)}/></Field><Field label="Rev."><input className={inputClass} value={form.rev} onChange={e => set('rev', e.target.value)} placeholder="Rev. 00"/></Field><Field label="วันนัดตรวจ"><input type="date" className={inputClass} value={form.appointment} onChange={e => set('appointment', e.target.value)}/></Field><Field label="เวลา"><input type="time" className={inputClass} value={form.time} onChange={e => set('time', e.target.value)}/></Field><Field label="ผู้ประสานงาน / SE"><input className={inputClass} value={form.coordinator} onChange={e => set('coordinator', e.target.value)}/></Field></div>
    <section className="rounded-xl border border-slate-200 p-3"><div className="mb-3 flex items-center justify-between"><b className="text-sm">Work Stage / Inspection Items</b><span className="text-xs text-slate-500">{selectedWorks.length} selected</span></div><div className="grid gap-2 sm:grid-cols-2">{INSPECTION_TASKS.map(task => <label key={task.partId} className="flex cursor-pointer items-start gap-2 rounded-lg border border-slate-100 p-2 text-xs hover:bg-slate-50"><input type="checkbox" checked={selectedWorks.includes(task.th)} onChange={() => toggleWork(task.th)} className="mt-0.5 accent-lime-500"/><span>{task.th}<small className="block text-[10px] text-slate-400">{task.en}</small></span></label>)}<label className="flex cursor-pointer items-start gap-2 rounded-lg border border-slate-100 p-2 text-xs hover:bg-slate-50"><input type="checkbox" checked={selectedWorks.includes(OTHER_WORK)} onChange={() => toggleWork(OTHER_WORK)} className="mt-0.5 accent-lime-500"/><span>อื่นๆ <small className="text-slate-400">(Other — specify)</small></span></label></div>{selectedWorks.includes(OTHER_WORK) && <Field label="ระบุรายการตรวจอื่นๆ / Custom Work Item" className="mt-3"><input className={inputClass} value={otherWork} onChange={e => setOtherWork(e.target.value)} placeholder="กรอกรายการตรวจงาน"/></Field>}</section>
    <section><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><b className="text-sm">Select Rooms <span className="text-slate-400">({form.rooms.length} selected)</span></b><button type="button" onClick={() => set('rooms', roomIds.every(room => form.rooms.includes(room)) ? form.rooms.filter(room => !roomIds.includes(room)) : [...new Set([...form.rooms, ...roomIds])])} className="text-xs font-semibold text-emerald-700">{roomIds.every(room => form.rooms.includes(room)) ? 'Clear this floor' : 'Select all rooms on floor'}</button></div><Field label="Floor"><select className={`${inputClass} mb-2 max-w-56`} value={selectedFloor} onChange={e => setSelectedFloor(Number(e.target.value))}>{Array.from({ length: project.floors }, (_, index) => index + 1).map(floor => <option key={floor} value={floor}>{floor === 1 ? 'ชั้น 1 · พื้นที่ส่วนกลาง / Floor 1 · Common Area' : `ชั้น ${floor} / Floor ${floor}`}</option>)}</select></Field><div className="grid max-h-44 grid-cols-3 gap-2 overflow-y-auto rounded-xl border border-slate-100 p-3 sm:grid-cols-6">{roomIds.map(room => <label key={room} className={`flex cursor-pointer items-center gap-1.5 rounded-lg border px-2 py-2 text-xs ${form.rooms.includes(room) ? 'border-lime-400 bg-lime-50 text-emerald-900' : 'border-slate-100'}`}><input type="checkbox" checked={form.rooms.includes(room)} onChange={() => toggleRoom(room)} className="accent-lime-500"/>{room === 'COMMON' ? 'Common Area' : room}</label>)}</div></section>
    <Field label="Reference File Attachment"><input type="file" multiple onChange={handleFiles} className="block w-full rounded-xl border border-dashed border-slate-300 bg-slate-50 px-3 py-3 text-xs"/>{form.attachmentNames.length > 0 && <p className="mt-1 text-xs text-slate-500">Attached: {form.attachmentNames.join(', ')}</p>}</Field>{error && <p role="alert" className="rounded-lg bg-rose-50 p-2 text-xs text-rose-700">{error}</p>}<div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit"><Send size={14}/>{request ? 'Save Schedule' : 'Create Request'}</Button></div></form></Modal>;
}

function RequestDetail({ request, onClose }) { const language = useContext(LanguageContext); return <Translated><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2">{[['Request No.',request.requestNo],['Rev.',request.rev ?? request.rootId ?? '—'],['Work Stage',getRequestedWorks(request).map(item => workLabel(item, language)).join(' · ')],['Appointment',`${request.appointment} · ${request.time}`],['Coordinator',request.coordinator],['Status',request.status],['Project ID',request.projectId]].map(([label,value]) => <div key={label} className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] text-slate-400">{label}</p><p className="mt-1 text-xs font-semibold">{value}</p></div>)}</div><div><b className="text-xs">Rooms</b><div className="mt-2 flex flex-wrap gap-2">{request.rooms.map(room => <Badge key={room} color="green">{room === 'COMMON' ? (language === 'TH' ? 'พื้นที่ส่วนกลาง' : 'Common Area') : room}</Badge>)}</div></div><div><b className="text-xs">Reference Files</b><p className="mt-1 text-xs text-slate-500">{request.attachmentNames?.join(', ') || 'No reference files attached'}</p></div><div className="flex justify-end"><Button variant="secondary" onClick={onClose}>Close</Button></div></div></Translated>; }

function InspectionModal({ project, request, event, draft, user, events, updateData, onClose, onToast, onCamera, onStopCamera, onCapture, videoRef, cameraState, language }) {
  const initial = draft || event || {}; const requestedWorks = getRequestedWorks(request);
  const [room, setRoom] = useState(String(initial.room || request.rooms.find(value => !events.some(item => item.requestId === request.id && String(item.room) === String(value))) || request.rooms[0] || ''));
  const [recorder, setRecorder] = useState(initial.recorder || user?.name || '');
  const [checklist, setChecklist] = useState(() => Object.fromEntries(requestedWorks.map(item => [item, initial.checklist?.[item] || 'ยังไม่ระบุ'])));
  const [note, setNote] = useState(initial.note || ''); const [reviseDoc, setReviseDoc] = useState(initial.reviseDoc || '');
  const [evidence, setEvidence] = useState(initial.evidence || []); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [cameraOpen, setCameraOpen] = useState(false);
  useEffect(() => { const handler = e => setEvidence(list => [...list, e.detail]); window.addEventListener('trex-add-photo', handler); return () => window.removeEventListener('trex-add-photo', handler); }, []);
  const addEvidenceFiles = async files => { const next = []; for (const file of files) { if (file.size > 5 * 1024 * 1024) { setError(`${file.name} exceeds the 5 MB prototype limit.`); continue; } try { next.push({ id: uid(), name: file.name, type: file.type, dataUrl: await compressImage(file) }); } catch { setError(`Could not read ${file.name}.`); } } setEvidence(current => [...current, ...next]); };
  const save = isDraft => {
    if (!room || !recorder.trim()) { setError('Select a room and enter the recorder name.'); return; }
    if (!isDraft && !Object.values(checklist).some(value => value !== 'ยังไม่ระบุ')) { setError('Complete at least one requested checklist item before saving.'); return; }
    setSaving(true);
    const values = Object.values(checklist); const result = values.includes('Fail') ? 'Fail' : values.length > 0 && values.every(value => value === 'Pass') ? 'Pass' : values.includes('In Progress') ? 'In Progress' : 'Pending';
    const record = { id: isDraft ? (draft?.id || uid()) : event?.id || uid(), projectId: project.id, requestId: request.id, requestNo: request.requestNo, room, stage: requestedWorks.join(' · '), requestedWorks, date: todayIso(), recorder: recorder.trim(), result, checklist, note, evidence, reviseDoc, savedAt: new Date().toISOString() };
    if (isDraft) { updateData(current => ({ ...current, drafts: [record, ...current.drafts.filter(item => item.id !== record.id)] })); onToast('Inspection draft saved.'); setSaving(false); onClose(); return; }
    updateData(current => { const nextEvents = current.events.some(item => item.id === record.id) ? current.events.map(item => item.id === record.id ? record : item) : [record, ...current.events]; const requestEvents = nextEvents.filter(item => item.requestId === request.id); const doneRooms = new Set(requestEvents.map(item => String(item.room))).size; const nextStatus = doneRooms >= request.rooms.length ? 'Completed' : 'Partially Inspected'; return { ...current, events: nextEvents, requests: current.requests.map(item => item.id === request.id ? { ...item, status: nextStatus } : item), drafts: current.drafts.filter(item => !(item.requestId === request.id && String(item.room) === String(room))) }; });
    onToast(`Inspection saved · ${result}`); setSaving(false); onClose();
  };
  return <Modal title={`${event ? 'Retry / Revise Inspection' : 'Inspection Form'} · ${request.requestNo}`} onClose={onClose} size="max-w-6xl"><div className="space-y-4"><div className="grid gap-3 rounded-2xl bg-emerald-950 p-4 text-white sm:grid-cols-4">{[['Project',project.name],['Schedule',`${request.appointment} · ${request.time}`],['Request',request.requestNo],['Work Stage',requestedWorks.join(' · ')]].map(([label,value]) => <div key={label}><p className="text-xs text-emerald-100/60">{label}</p><b className="mt-1 block text-sm">{value}</b></div>)}</div><div className="grid gap-4 lg:grid-cols-[1fr_.9fr]"><section className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="เลือกห้องที่กำลังตรวจ"><select className={inputClass} value={room} onChange={e => setRoom(e.target.value)}>{request.rooms.map(value => <option key={value} value={value}>{value === 'COMMON' ? 'Common Area' : value}</option>)}</select></Field><Field label="ผู้บันทึก (SE)"><input className={inputClass} value={recorder} onChange={e => setRecorder(e.target.value)}/></Field></div><Card title="Inspection Checklist" subtitle="Only the work items requested in this RI"><div className="space-y-2">{requestedWorks.map(item => <Field key={item} label={item}><select value={checklist[item] || 'ยังไม่ระบุ'} onChange={e => setChecklist(current => ({ ...current, [item]: e.target.value }))} className={inputClass}><option value="ยังไม่ระบุ">ยังไม่ระบุ</option><option value="Pass">Pass</option><option value="In Progress">In Progress</option><option value="Fail">Fail</option></select></Field>)}</div><div className="mt-3"><RoomModelViewer3D room={room} taskStates={checklist} language={language} compact workFilter="ALL"/></div></Card><Field label="Inspection Note"><textarea className={`${inputClass} min-h-24 resize-y`} value={note} onChange={e => setNote(e.target.value)} placeholder="Notes for the project record"/></Field>{event && <Field label="Revise Doc."><input className={inputClass} value={reviseDoc} onChange={e => setReviseDoc(e.target.value)} placeholder="Revision reference / reason"/></Field>}</section>
      <section><Card title="Add Photos / Evidence" subtitle="Capture with camera or upload image files"><div className="flex flex-wrap gap-2"><Button type="button" variant="secondary" onClick={() => { setCameraOpen(true); onCamera(); }}><Camera size={15}/>Open Camera</Button><label className="inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3.5 py-2 text-sm font-semibold hover:bg-slate-50"><Upload size={15}/>Add Photos<input type="file" accept="image/*" capture="environment" multiple className="hidden" onChange={e => addEvidenceFiles([...e.target.files])}/></label></div>{evidence.length > 0 ? <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">{evidence.map(photo => <div key={photo.id} className="relative overflow-hidden rounded-xl border border-slate-200">{photo.dataUrl && photo.type.startsWith('image/') ? <img src={photo.dataUrl} alt={photo.name} className="h-24 w-full object-cover"/> : <div className="grid h-24 place-items-center bg-slate-50"><FileText/></div>}<p className="truncate p-2 text-xs">{photo.name}</p><button type="button" aria-label="Remove photo" onClick={() => setEvidence(list => list.filter(value => value.id !== photo.id))} className="absolute right-1 top-1 rounded-full bg-white/90 p-1.5 text-rose-600"><X size={13}/></button></div>)}</div> : <p className="mt-3 rounded-xl bg-slate-50 p-3 text-xs text-slate-400">No evidence attached yet.</p>}{cameraOpen && <div className="mt-3 rounded-xl bg-emerald-950 p-3 text-white">{cameraState === 'active' ? <><video ref={videoRef} autoPlay playsInline className="max-h-72 w-full rounded-lg bg-black object-contain"/><div className="mt-2 flex gap-2"><Button type="button" onClick={() => onCapture(room, project.id, request.requestNo)}><Camera size={14}/>Capture photo</Button><Button type="button" variant="secondary" onClick={() => { onStopCamera(); setCameraOpen(false); }}>Close camera</Button></div></> : <div className="flex items-center justify-between gap-2"><p className="text-sm">{cameraState === 'requesting' ? 'Requesting camera permission…' : 'Camera unavailable. Use Add Photos to select an image.'}</p><Button type="button" variant="secondary" onClick={() => { onStopCamera(); setCameraOpen(false); }}>Close</Button></div>}</div>}</Card></section></div>
    {error && <p role="alert" className="rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}<div className="flex flex-wrap justify-end gap-2 border-t border-slate-100 pt-4"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="button" variant="secondary" disabled={saving} onClick={() => save(true)}>Save draft</Button><Button type="button" disabled={saving} onClick={() => save(false)}><CheckCircle2 size={15}/>{saving ? 'Saving…' : 'Save Inspection Event'}</Button></div></div></Modal>;
}

function EventDetail({ event, onClose }) { return <Translated><div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-slate-50 p-4"><div><b>{event.requestNo} · Room {event.room}</b><p className="mt-1 text-xs text-slate-500">{event.stage} · {event.date} · {event.recorder}</p></div><ResultBadge status={event.result}/></div><div className="grid gap-2 sm:grid-cols-2">{Object.entries(event.checklist || {}).map(([label,value]) => <div key={label} className="flex justify-between rounded-xl border border-slate-100 p-3 text-xs"><span>{label}</span><Badge color={value === 'Pass' ? 'green' : value === 'Fail' ? 'rose' : 'slate'}>{value}</Badge></div>)}</div><div className="rounded-xl bg-slate-50 p-3"><b className="text-xs">Defect / Summary</b><p className="mt-1 text-xs text-slate-600">{event.defect || 'No defect recorded'}</p><p className="mt-2 text-[10px] text-slate-500">Location: {event.location || '—'}</p><p className="mt-1 text-[10px] text-slate-500">Note: {event.note || '—'}</p></div><div><b className="text-xs">Evidence</b><div className="mt-2 flex flex-wrap gap-2">{event.evidence?.map(file => <a key={file.id} href={file.dataUrl || '#'} onClick={e => { if (!file.dataUrl) e.preventDefault(); }} target="_blank" rel="noreferrer" className="flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-xs"><FileText size={14}/>{file.name}</a>)}{!event.evidence?.length && <p className="text-xs text-slate-400">No evidence attached.</p>}</div></div><div className="flex justify-end"><Button variant="secondary" onClick={onClose}>Close</Button></div></div></Translated>; }

function DocumentModal({ project, doc, requests, floors, onClose, onToast, updateData }) {
  const [form, setForm] = useState(() => doc ? { ...doc, floor: String(doc.floor || 2), room: String(doc.room || '201') } : { name: '', type: 'Inspection Report', requestNo: requests[0]?.requestNo || '', building: 'Building A', floor: '2', room: '201', round: 'Round 1', date: todayIso(), uploadedBy: 'Phattarawadee Sroiphap', dataUrl: '', size: '' });
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const submit = async e => { e.preventDefault(); if (!form.name.trim()) { setError('Choose a file or enter a document name.'); return; } setBusy(true); const record = { ...form, id: doc?.id || uid(), projectId: project.id, uploadedBy: form.uploadedBy || 'Site Engineer' }; updateData(c => ({ ...c, docs: doc ? c.docs.map(d => d.id === doc.id ? record : d) : [record, ...c.docs] })); onToast(doc ? 'Document updated.' : 'Document uploaded to this prototype.'); setBusy(false); onClose(); };
  const pickFile = async file => { if (!file) return; if (file.size > 5 * 1024 * 1024) { setError('File exceeds the 5 MB prototype limit.'); return; } setForm(f => ({ ...f, name: file.name, size: file.size > 1024 * 1024 ? `${(file.size / 1024 / 1024).toFixed(1)} MB` : `${Math.round(file.size / 1024)} KB` })); if (file.size <= 1_700_000) { try { setForm(f => ({ ...f, name: file.name, size: file.size > 1024 * 1024 ? `${(file.size / 1024 / 1024).toFixed(1)} MB` : `${Math.round(file.size / 1024)} KB` })); const dataUrl = await fileToDataUrl(file); setForm(f => ({ ...f, name: file.name, dataUrl })); } catch { setError('Could not read this file.'); } } else setError('Large file metadata is saved; choose a file under 1.7 MB to embed it for preview/download in this prototype.'); };
  return <Modal title={doc ? 'Edit Project Document' : 'Upload Project Document'} onClose={onClose} size="max-w-2xl"><form onSubmit={submit} className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Choose File"><input type="file" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.docx" className="block w-full rounded-xl border border-dashed border-slate-300 p-3 text-xs" onChange={e => pickFile(e.target.files?.[0])}/></Field><Field label="Document Name"><input className={inputClass} value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="File name"/></Field><Field label="Document Type"><select className={inputClass} value={form.type} onChange={e => setForm({ ...form, type: e.target.value })}>{['Drawing','Request / RI','Inspection Report','Checklist','Site Photo','Other'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Request"><select className={inputClass} value={form.requestNo} onChange={e => setForm({ ...form, requestNo: e.target.value })}><option value="">No request linked</option>{requests.map(r => <option key={r.id}>{r.requestNo}</option>)}</select></Field><Field label="Building"><select className={inputClass} value={form.building} onChange={e => setForm({ ...form, building: e.target.value })}><option>Building A</option><option>Building B</option></select></Field><Field label="Floor"><select className={inputClass} value={form.floor} onChange={e => { const floor = e.target.value; setForm(current => ({ ...current, floor, room: floor === '1' ? 'COMMON' : `${floor}01` })); }}>{floors.map(f => <option key={f} value={f}>{f === 1 ? 'Floor 1 · Common Area' : `Floor ${f}`}</option>)}</select></Field><Field label="Room"><input className={inputClass} value={form.room} onChange={e => setForm({ ...form, room: e.target.value })} readOnly={form.floor === '1'} placeholder="201"/></Field><Field label="Inspection Round"><select className={inputClass} value={form.round} onChange={e => setForm({ ...form, round: e.target.value })}>{['Round 1','Round 2','Round 3','Final'].map(x => <option key={x}>{x}</option>)}</select></Field><Field label="Document Date"><input type="date" className={inputClass} value={form.date} onChange={e => setForm({ ...form, date: e.target.value })}/></Field></div>{error && <p role="alert" className="rounded-lg bg-amber-50 p-2 text-xs text-amber-800">{error}</p>}<div className="flex justify-end gap-2 border-t border-slate-100 pt-4"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit" disabled={busy}>{doc ? <Pencil size={14}/> : <Upload size={14}/>} {busy ? 'Saving…' : doc ? 'Save Changes' : 'Upload Document'}</Button></div></form></Modal>;
}

function DocumentDetail({ doc, onClose }) { const isImage = doc.dataUrl && doc.dataUrl.startsWith('data:image/'); const isPdf = doc.dataUrl && doc.dataUrl.startsWith('data:application/pdf'); return <Modal title="Document Preview" onClose={onClose} size="max-w-4xl"><div className="space-y-4"><div className="flex flex-wrap items-start justify-between gap-3 rounded-xl bg-slate-50 p-4"><div><b className="text-sm">{doc.name}</b><p className="mt-1 text-xs text-slate-500">{doc.type} · {doc.requestNo || 'No request'} · Room {doc.room}</p><p className="mt-1 text-[10px] text-slate-400">{doc.building} · Floor {doc.floor} · {doc.round} · {doc.date} · {doc.size}</p></div><Button variant="secondary" onClick={() => downloadRecord(doc, doc.name)}><Download size={14}/>Download</Button></div>{isImage ? <div className="grid max-h-[60vh] place-items-center overflow-auto rounded-xl bg-slate-100 p-3"><img src={doc.dataUrl} alt={doc.name} className="max-h-[55vh] max-w-full object-contain"/></div> : isPdf ? <iframe title={doc.name} src={doc.dataUrl} className="h-[60vh] w-full rounded-xl border border-slate-200"/> : <div className="grid min-h-48 place-items-center rounded-xl border border-dashed border-slate-200 bg-slate-50 text-center"><div><FileText size={30} className="mx-auto text-emerald-700"/><p className="mt-2 text-sm font-semibold">{doc.name}</p><p className="mt-1 text-xs text-slate-500">Preview is not embedded for this mock record. Download its project record metadata or attach a local file under 1.7 MB.</p></div></div>}<div className="flex justify-end"><Button variant="secondary" onClick={onClose}>Close</Button></div></div></Modal>; }
